if (firstQuestion !== expectedQuestion) {
  nodeStatus.first_llm_node.success = false;
  nodeStatus.first_llm_node.reason = 'The first LLM response did not exactly match the required question.';
  console.log(JSON.stringify({ event: 'workflow_validation_failed', node: 'first_llm_node', nodeStatus }));
  throw new Error(nodeStatus.first_llm_node.reason);
}

